add_task.function:
def add_task(data, task):
    data.setdefault('tasks', []).append(task)
    return data

set_task_completed.function:
def set_task_completed(data, task_id, completed=True):
    for task in data.get('tasks', []):
        if task.get('id') == task_id:
            task['is_completed'] = bool(completed)
            return data
    raise KeyError(task_id)

add_memory.function:
def add_memory(data, entry):
    data.setdefault('memory', []).append(entry)
    return data
